import json, os, sys, collections

D='/app/export'
res=collections.defaultdict(list)
for fn in os.listdir(D):
    if not fn.endswith('.ndjson'): continue
    for line in open(os.path.join(D,fn)):
        line=line.strip()
        if line: res[fn[:-7]].append(json.loads(line))

EXT='https://chartr.example/fhir/StructureDefinition/'
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url']==EXT+name:
            for k,v in e.items():
                if k.startswith('value'): return v
    return None

def subj(r):
    for k in ('subject','patient','for'):
        if k in r and isinstance(r[k],dict) and 'reference' in r[k]:
            return r[k]['reference'].split('/')[-1]
    return None

def et(r):
    return ext(r,'event-time') or r.get('date') or r.get('recordedDate') or ''

byp=collections.defaultdict(list)
noP=[]
for t,lst in res.items():
    for r in lst:
        if t=='Patient': continue
        s=subj(r)
        if s: byp[s].append(r)
        else: noP.append(r)

pats={p['id']:p for p in res['Patient']}
eps=collections.defaultdict(list)
for e in res['EpisodeOfCare']: eps[subj(e)].append(e)

def fmt(r):
    t=r['resourceType']; i=r['id']; T=et(r)
    out=[f"  [{T}] {t}/{i}"]
    def add(s): out.append("      "+s)
    if t=='Condition':
        add(f"code={r.get('code',{}).get('text')} recordedDate={r.get('recordedDate')} recorder={r.get('recorder',{}).get('display')} clinicalStatus={r.get('clinicalStatus',{}).get('coding',[{}])[0].get('code')} verif={r.get('verificationStatus',{}).get('coding',[{}])[0].get('code')}")
        if r.get('note'): add("note: "+" | ".join(n['text'] for n in r['note']))
    elif t=='Observation':
        add(f"test={r.get('code',{}).get('text')} status={r['status']} collected={r.get('effectiveDateTime')} issued={r.get('issued')} value={r.get('valueString')}")
        add(f"accession={[x.get('value') for x in r.get('identifier',[])]} specimen={r.get('specimen',{}).get('reference')}")
        if r.get('note'): add("note: "+" | ".join(n['text'] for n in r['note']))
